function field(form,label,value='',type='text',required=false){const l=node('label',label),i=node(type==='textarea'?'textarea':'input');if(type!=='textarea')i.type=type;i.value=value??'';i.required=required;if(type==='text'||type==='textarea')i.maxLength=type==='textarea'?2000:160;if(type==='number'){i.min=0;i.step='1';i.inputMode='numeric';if(label.includes('熱量')&&i.value!==''&&!Number.isInteger(Number(i.value))){i.step='any';i.addEventListener('input',()=>{i.step='1';});}}l.append(i);form.append(l);return i;}
